629	    pub async fn open(&self, ino: InodeNo, flags: i32, pid: u32) -> Result<Opened, Error> {
630	        trace!("fs:open with ino {:?} flags {:#b} pid {:?}", ino, flags, pid);
631	
632	        #[cfg(not(target_os = "linux"))]
633	        let direct_io = false;
634	        #[cfg(target_os = "linux")]
635	        let direct_io = flags & libc::O_DIRECT != 0;
636	
637	        let force_revalidate = !self.config.cache_config.serve_lookup_from_cache || direct_io;
638	        let lookup = self.superblock.getattr(&self.client, ino, force_revalidate).await?;
639	
640	        match lookup.inode.kind() {
641	            InodeKind::Directory => return Err(InodeError::IsDirectory(lookup.inode.err()).into()),
642	            InodeKind::File => (),
643	        }
644	
645	        let inode = lookup.inode.clone();
646	        let full_key = lookup.inode.full_key().to_owned();
647	        let remote_file = lookup.inode.is_remote()?;
648	
649	        // Open with O_APPEND is ok for new files because it's same as creating a new one.
650	        // but we can't support it on existing files and we should explicitly say we don't allow that.
651	        if remote_file && (flags & libc::O_APPEND != 0) {
652	            return Err(err!(libc::EINVAL, "O_APPEND is not supported on existing files"));
653	        }
654	
655	        // We can't support O_SYNC writes because they require the data to go to stable storage
656	        // at `write` time, but we only commit a PUT at `close` time.
657	        if flags & (libc::O_SYNC | libc::O_DSYNC) != 0 {
658	            return Err(err!(libc::EINVAL, "O_SYNC and O_DSYNC are not supported"));
659	        }
660	
661	        // All file handles will be lazy initialized on first read/write.
662	        let state = FileHandleState::new(lookup, flags, pid).await.into();
663	        let fh = self.next_handle();
664	        let handle = FileHandle { inode, full_key, state };
665	        debug!(fh, ino, "new file handle created");
666	        self.file_handles.write().await.insert(fh, Arc::new(handle));
667	
668	        let reply_flags = if direct_io { FOPEN_DIRECT_IO } else { 0 };
669	
670	        Ok(Opened { fh, flags: reply_flags })
